import { createWorkflowChain } from '@voltagent/core';

interface WorkflowInput {
  value: number;
  operation: string;
}

interface WorkflowOutput {
  result: number;
}

const workflow = createWorkflowChain<WorkflowInput, WorkflowOutput>()
  .andWhen(
    (input) => input.operation === 'double',
    (input) => ({ result: input.value * 2 })
  )
  .andWhen(
    (input) => input.operation === 'square',
    (input) => ({ result: input.value * input.value })
  )
  .build();

export default workflow;

